<script setup lang="ts">import{VALUE_KEYS,VALUE_LABELS,type ValueKey,type ValueWeights}from'../../core/models';import{PRESETS,normalizeWeights}from'../../core/weight-service';const props=defineProps<{weights:ValueWeights}>();const emit=defineEmits<{update:[w:ValueWeights]}>();function set(key:ValueKey,value:number){emit('update',{...props.weights,[key]:value})}function percent(key:ValueKey){try{return normalizeWeights(props.weights)[key]}catch{return 0}}</script>
<template><section class="paper-panel values"><span class="index">02 / VALUES</span><h2>什么对你更重要？</h2><p>权重没有对错，它只决定模拟器从哪个角度理解“后悔”。</p><div class="preset-list"><button v-for="(weights,name) in PRESETS" :key="name" @click="emit('update',{...weights})">{{name}}</button></div><label v-for="key in VALUE_KEYS" :key="key"><span>{{VALUE_LABELS[key]}}<b>{{percent(key)}}%</b></span><input type="range" min="0" max="100" :value="weights[key]" @input="set(key,Number(($event.target as HTMLInputElement).value))"></label></section></template>
